const P = ctx.params;
const themes = [[0x0b1220, 0xf8fafc, 0x818cf8], [0xf5f7f8, 0x0d1f22, 0x0f766e], [0xfdf6ff, 0x3b1f56, 0x7c4ddb], [0xeceef2, 0x33303a, 0xaf4027]];
let ti = 0, score = 0, flips = 0, t = 40, pair = 0;
const card = new PIXI.Graphics();
card.x = 16; card.y = 14;
ctx.stage.addChild(card);
const cap = ctx.text('live preview', { size: 10, color: ctx.colors.dim });
cap.x = 16; cap.y = 84;
ctx.stage.addChild(cap);
function paint(broken) {
  const th = themes[ti];
  card.clear();
  card.roundRect(0, 0, 132, 64, 10).fill({ color: th[0] }).stroke({ width: 2, color: broken ? ctx.colors.bad : th[2], alpha: 0.9 });
  card.roundRect(12, 12, 76, 7, 3).fill({ color: th[1], alpha: 0.75 });
  card.roundRect(12, 25, 50, 6, 3).fill({ color: th[1], alpha: 0.3 });
  card.roundRect(12, 40, 58, 14, 7).fill({ color: broken ? 0xf43f5e : th[2] });
}
paint(false);
const pad = ctx.chip('semantic only', { color: ctx.colors.g1, minWidth: 156, size: 12 });
pad.y = ctx.height - 26;
pad.x = ctx.width / 2;
ctx.stage.addChild(pad);
const onMove = (e) => { pad.x = Math.max(84, Math.min(ctx.width - 84, e.global.x)); };
ctx.app.stage.on('pointermove', onMove);
ctx.onDestroy(() => ctx.app.stage.off('pointermove', onMove));
ctx.api.setGoal('0 / ' + P.target);
const live = [];
ctx.onTick((dt) => {
  t += dt;
  if (t > 58) {
    t = 0;
    const i = pair % P.tokens.length;
    pair++;
    const left = Math.random() < 0.5;
    const lanes = [ctx.width * 0.3, ctx.width * 0.7];
    const add = (label, good, x) => {
      const c = ctx.chip(label, { color: 0x1b2030, textColor: 0xe4ebff, stroke: ctx.colors.g3, size: 12 });
      c.x = x; c.y = -18; c.good = good;
      ctx.stage.addChild(c); live.push(c);
    };
    add(P.tokens[i], true, lanes[left ? 0 : 1]);
    add(P.hexes[i], false, lanes[left ? 1 : 0]);
  }
  for (let k = live.length - 1; k >= 0; k--) {
    const c = live[k];
    c.y += 2.2 * dt;
    const hit = c.y > pad.y - 20 && c.y < pad.y + 20 && Math.abs(c.x - pad.x) < 88;
    if (!hit) {
      if (c.y > ctx.height + 24) { live.splice(k, 1); c.destroy(); }
      continue;
    }
    live.splice(k, 1);
    c.destroy();
    if (c.good) {
      score++;
      ctx.api.setScore(score);
      ctx.api.setGoal(score + ' / ' + P.target);
      gsap.to(pad.scale, { x: 1.16, y: 1.16, duration: 0.1, onComplete: () => gsap.to(pad.scale, { x: 1, y: 1, duration: 0.22, ease: 'back.out' }) });
      if (score >= P.target) { ctx.api.win('Every value stayed semantic. That page survives all six themes.'); return; }
    } else {
      flips++;
      ti = (ti + 1) % themes.length;
      paint(true);
      gsap.delayedCall(0.55, () => paint(false));
      ctx.api.setGoal(score + ' / ' + P.target + '  -  ' + (3 - flips) + ' flips left');
      if (flips >= 3) { ctx.api.fail('Three hard-coded values, three themes they were wrong on.'); return; }
    }
  }
});

